// Starter structures — hand-built prefabs for /place. Never generated by
// worldgen (kept out of STRUCTURES, so registration order is untouched).
// Each builder takes (x, y, z) = north-west corner at ground level: y is the
// first air layer, floors sit at y - 1.

import Foundation

public struct StarterStructure {
    public let id: String
    public let build: (Builder, Int, Int, Int) -> Void
}

public let STARTER_STRUCTURES: [StarterStructure] = [
    StarterStructure(id: "cabin", build: starterCabin),
    StarterStructure(id: "watchtower", build: starterWatchtower),
    StarterStructure(id: "bunker", build: starterBunker),
    StarterStructure(id: "farm", build: starterFarm),
    StarterStructure(id: "portal", build: starterPortal),
    StarterStructure(id: "giza_pyramid", build: starterPyramid),
    StarterStructure(id: "castle", build: starterCastle),
    StarterStructure(id: "lighthouse", build: starterLighthouse),
    StarterStructure(id: "windmill", build: starterWindmill),
    StarterStructure(id: "treehouse", build: starterTreehouse),
    StarterStructure(id: "sky_island", build: starterSkyIsland),
    StarterStructure(id: "city", build: starterCity),
    StarterStructure(id: "small_school", build: starterSmallSchool),
    StarterStructure(id: "large_school", build: starterLargeSchool),
    StarterStructure(id: "eiffel_tower", build: starterEiffelTower),
    StarterStructure(id: "stonehenge", build: starterStonehenge),
    StarterStructure(id: "colosseum", build: starterColosseum),
    StarterStructure(id: "devils_tower", build: starterDevilsTower),
]

@inline(__always) private func C(_ b: UInt16, _ m: Int = 0) -> Int { Int(cell(b, m)) }
private let AIR = 0

func kitChest(_ b: Builder, _ x: Int, _ y: Int, _ z: Int, _ facing: Int, _ items: String) {
    b.set(x, y, z, C(B.chest, facing))
    b.s.addBlockEntity(BESpec(x: x, y: y, z: z, kind: "chest_items", data: ["items": .str(items)]))
}
/// door on a north/south/east/west wall: lower half `facing`, upper half 8
func door(_ b: Builder, _ x: Int, _ y: Int, _ z: Int, _ facing: Int) {
    b.set(x, y, z, C(B.oak_door, facing))
    b.set(x, y + 1, z, C(B.oak_door, 8))
}
/// bed with its foot at (x,z), head one step toward `facing`
func bed(_ b: Builder, _ x: Int, _ y: Int, _ z: Int, _ facing: Int) {
    b.set(x, y, z, C(B.red_bed, facing))
    b.set(x + [0, 0, -1, 1][facing], y, z + [-1, 1, 0, 0][facing], C(B.red_bed, facing | 4))
}

/// 10-tall fence pole with a red wool flag and a glowstone tip — easy to spot
func flag(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    for py in y...(y + 9) { b.set(x, py, z, C(B.oak_fence)) }
    for fy in (y + 7)...(y + 9) { for fx in 1...3 { b.set(x + fx, fy, z, C(B.red_wool)) } }
    b.set(x, y + 10, z, C(B.glowstone))
}

// 9×9 spruce cabin: bed, crafting table, furnace, stocked chest, gable roof
private func starterCabin(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    let planks = C(B.spruce_planks), log = C(B.spruce_log), win = C(B.glass_pane)
    b.fill(x, y - 1, z, x + 8, y - 1, z + 8, C(B.cobblestone))
    b.fill(x + 1, y - 1, z + 1, x + 7, y - 1, z + 7, C(B.oak_planks))
    b.fill(x + 1, y, z + 1, x + 7, y + 3, z + 7, AIR)
    for h in 0..<4 {
        for d in 0...8 {
            let mid = h >= 1 && h <= 2 && (d == 2 || d == 6)
            b.set(x + d, y + h, z, mid ? win : planks)
            b.set(x + d, y + h, z + 8, mid ? win : planks)
            b.set(x, y + h, z + d, mid ? win : planks)
            b.set(x + 8, y + h, z + d, mid ? win : planks)
        }
        for (cx, cz) in [(0, 0), (8, 0), (0, 8), (8, 8)] { b.set(x + cx, y + h, z + cz, log) }
    }
    // gable roof: stairs climbing from both long sides to a plank ridge
    for i in 0...4 {
        let ry = y + 4 + i
        for dx in -1...9 {
            b.set(x + dx, ry, z - 1 + i, C(B.spruce_stairs, 1))
            b.set(x + dx, ry, z + 9 - i, C(B.spruce_stairs, 0))
        }
        if i < 4 {
            for dz in (i)...(8 - i) {
                b.set(x, ry, z + dz, planks)
                b.set(x + 8, ry, z + dz, planks)
                for dx in 1...7 { b.set(x + dx, ry, z + dz, AIR) }
            }
        }
    }
    for dx in -1...9 {
        b.set(x + dx, y + 8, z + 4, planks)
        b.set(x + dx, y + 9, z + 4, C(B.spruce_slab))
    }
    door(b, x + 4, y, z, 0)
    b.fill(x + 3, y - 1, z - 2, x + 5, y - 1, z - 1, C(B.cobblestone))
    bed(b, x + 6, y, z + 5, 1)
    b.set(x + 1, y, z + 7, C(B.crafting_table))
    b.set(x + 2, y, z + 7, C(B.furnace, 0))
    kitChest(b, x + 3, y, z + 7, 0,
             "stone_pickaxe,stone_axe,stone_shovel,stone_sword,bread*16,torch*32,oak_log*16,cobblestone*32,coal*8")
    b.set(x + 1, y + 1, z + 7, C(B.torch))
    b.set(x + 7, y, z + 1, C(B.lantern))
    b.set(x + 1, y, z + 1, C(B.lantern))
}

// 5×5 cobblestone tower, ladder to a fenced 9×9 lookout with a slab roof
private func starterWatchtower(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    let cobble = C(B.cobblestone), planks = C(B.spruce_planks), fence = C(B.spruce_fence)
    let top = y + 15
    b.fill(x, y - 1, z, x + 4, y - 1, z + 4, cobble)
    b.walls(x, y, z, x + 4, top - 1, z + 4, cobble, AIR)
    b.fill(x + 1, y, z + 1, x + 3, top - 1, z + 3, AIR) // walls() closes top/bottom; reopen
    for (wx, wy, wz) in [(x + 2, y + 5, z), (x, y + 8, z + 2), (x + 4, y + 11, z + 2), (x + 2, y + 13, z + 4)] {
        b.set(wx, wy, wz, AIR) // arrow slits
    }
    door(b, x + 2, y, z, 0)
    b.fill(x + 2, y - 1, z - 2, x + 2, y - 1, z - 1, cobble)
    for h in y...top { b.set(x + 2, h, z + 3, C(B.ladder, 0)) }
    b.set(x + 1, y, z + 1, C(B.torch))
    b.set(x + 3, y, z + 1, C(B.torch))
    // lookout deck
    b.fill(x - 2, top, z - 2, x + 6, top, z + 6, planks)
    b.set(x + 2, top, z + 3, C(B.ladder, 0))
    b.fill(x - 2, top + 1, z - 2, x + 6, top + 3, z + 6, AIR)
    for d in -2...6 {
        for (fx, fz) in [(x + d, z - 2), (x + d, z + 6), (x - 2, z + d), (x + 6, z + d)] {
            b.set(fx, top + 1, fz, fence)
        }
    }
    for (px, pz) in [(x - 2, z - 2), (x + 6, z - 2), (x - 2, z + 6), (x + 6, z + 6)] {
        b.set(px, top + 2, pz, fence)
        b.set(px, top + 3, pz, fence)
    }
    b.fill(x - 2, top + 4, z - 2, x + 6, top + 4, z + 6, C(B.spruce_slab))
    b.set(x + 2, top + 3, z + 2, C(B.lantern, 1))
    kitChest(b, x + 5, top + 1, z + 5, 0, "bow,arrow*64,spyglass,cooked_beef*16")
}

// stone-brick hut over a ladder shaft into a 9×9 room 14 blocks down
private func starterBunker(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    let brick = C(B.stone_bricks)
    let fy = y - 14 // room floor layer (first air)
    // room shell + interior
    b.walls(x - 4, fy - 1, z - 3, x + 6, fy + 4, z + 7, brick, AIR)
    b.fill(x - 3, fy - 1, z - 2, x + 5, fy - 1, z + 6, C(B.smooth_stone))
    for (gx, gz) in [(x - 1, z), (x + 3, z), (x - 1, z + 4), (x + 3, z + 4)] { b.set(gx, fy + 4, gz, C(B.glowstone)) }
    // shaft from the room ceiling to the hut, ladder on its south wall
    for sy in (fy + 4)...(y - 1) {
        for dz in 0...2 { for dx in 0...2 { b.set(x + dx, sy, z + dz, dx == 1 && dz == 1 ? AIR : brick) } }
    }
    b.fill(x + 1, fy, z + 2, x + 1, fy + 3, z + 2, brick) // pillar carrying the ladder to the floor
    // surface hut
    b.walls(x, y - 1, z, x + 2, y + 2, z + 2, brick, AIR)
    for ly in fy...(y + 1) { b.set(x + 1, ly, z + 1, C(B.ladder, 0)) }
    b.fill(x - 1, y + 3, z - 1, x + 3, y + 3, z + 3, C(B.stone_brick_slab))
    door(b, x + 1, y, z, 0)
    b.set(x + 1, y + 2, z + 1, AIR)
    flag(b, x + 4, y, z + 3)
    // furnishings
    bed(b, x - 3, fy, z + 5, 0)
    bed(b, x - 2, fy, z + 5, 0)
    b.set(x + 5, fy, z + 6, C(B.crafting_table))
    b.set(x + 4, fy, z + 6, C(B.furnace, 0))
    b.set(x + 3, fy, z + 6, C(B.furnace, 0))
    kitChest(b, x + 5, fy, z - 2, 1, "bread*32,cooked_porkchop*16,torch*64,iron_pickaxe,iron_sword,shield")
    kitChest(b, x + 4, fy, z - 2, 1, "cobblestone*64,oak_planks*64,coal*16,iron_ingot*8")
    b.set(x + 3, fy, z - 2, C(B.barrel, 1))
    for (lx, lz) in [(x - 3, z - 2), (x + 5, z + 2)] { b.set(lx, fy, lz, C(B.lantern)) }
}

// 11×11 fenced plot: farmland rows either side of a water channel
private func starterFarm(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    let fence = C(B.oak_fence)
    b.fill(x, y - 2, z, x + 10, y - 2, z + 10, C(B.dirt))
    b.fill(x, y - 1, z, x + 10, y - 1, z + 10, C(B.grass_block))
    b.fill(x, y, z, x + 10, y + 2, z + 10, AIR)
    for d in 0...10 {
        for (fx, fz) in [(x + d, z), (x + d, z + 10), (x, z + d), (x + 10, z + d)] { b.set(fx, y, fz, fence) }
    }
    b.set(x + 5, y, z, C(B.oak_fence_gate, 0))
    let crops: [Int] = [C(B.wheat, 7), C(B.carrots, 7), C(B.potatoes, 7), C(B.beetroots, 3)]
    for dz in 1...9 {
        for dx in 1...9 {
            if dx == 5 {
                b.set(x + dx, y - 1, z + dz, C(B.water))
                continue
            }
            b.set(x + dx, y - 1, z + dz, C(B.farmland, 7))
            b.set(x + dx, y, z + dz, crops[((dx - 1) / 2) % crops.count])
        }
    }
    b.set(x + 5, y, z + 1, AIR) // path in from the gate
    b.set(x + 5, y - 1, z + 1, C(B.oak_planks))
    b.set(x + 1, y, z + 1, C(B.composter))
    for (px, pz) in [(x, z), (x + 10, z), (x, z + 10), (x + 10, z + 10)] {
        b.set(px, y + 1, pz, fence)
        b.set(px, y + 2, pz, C(B.lantern))
    }
    kitChest(b, x + 9, y, z + 1, 0, "wheat_seeds*32,carrot*16,potato*16,beetroot_seeds*16,bone_meal*32,iron_hoe")
}

// obsidian portal frame on a stone-brick pad, flint and steel in the chest
private func starterPortal(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    b.fill(x - 2, y - 1, z - 2, x + 5, y - 1, z + 2, C(B.stone_bricks))
    b.fill(x - 2, y, z - 2, x + 5, y + 5, z + 2, AIR)
    for dx in 0...3 {
        for dy in 0...4 where dx == 0 || dx == 3 || dy == 0 || dy == 4 {
            b.set(x + dx, y + dy, z, C(B.obsidian))
        }
    }
    kitChest(b, x + 5, y, z + 2, 0, "flint_and_steel,obsidian*10,cooked_beef*16")
    for (lx, lz) in [(x - 2, z - 2), (x + 5, z - 2), (x - 2, z + 2)] { b.set(lx, y, lz, C(B.lantern)) }
}
